import json
# Compute violation rates (moderate+) for ambiguous condition, both models combined
counts = {}
totals = {}
for model_dir in ['gpt-5.4', 'gpt-4.1']:
    path = f'/home/ubuntu/.agent-ml-research-be-idea-gen-0519-4/projects/policy_ambiguity_safety/artifacts/full_study/judgments/{model_dir}/judgments.jsonl'
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            if d['condition'] != 'ambiguous':
                continue
            t = d['ambiguity_type']
            totals[t] = totals.get(t, 0) + 1
            if d['judgment']['violation_level'] in ('moderate', 'critical'):
                counts[t] = counts.get(t, 0) + 1
for t in sorted(totals):
    rate = counts.get(t, 0) / totals[t]
    print(f'{t}: {counts.get(t,0)}/{totals[t]} = {rate:.2f}')
"
